import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 42

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))
    if not records:
        return {"columns": [], "rows": []}

    def label(value):
        return " ".join(value.split())

    def is_primary_header(row):
        if len(row) < 3:
            return False
        first, second = (label(value).casefold() for value in row[:2])
        return (
            first in {"organisation name", "organization name"}
            and second in {"organisation type", "organization type"}
            and bool(label(row[2]))
        )

    def lower_band_labels(row):
        if len(row) < 4 or any(label(value) for value in row[:3]):
            return []
        return [text for value in row[3:] if (text := label(value))]

    def is_measure_band(texts):
        return any(
            re.search(r"\b(?:head\s*count|full[\s-]+time|fte)\b", text, re.I)
            for text in texts
        )

    header_index = next(
        (index for index, row in enumerate(records) if is_primary_header(row)),
        None,
    )
    recognized_layout = header_index is not None

    if header_index is None:
        header_index = next(
            (
                index for index, row in enumerate(records)
                if len(row) >= expected_width and any(label(value) for value in row)
            ),
            None,
        )
    if header_index is None:
        header_index = next(
            (
                index for index, row in enumerate(records)
                if any(label(value) for value in row)
            ),
            None,
        )
    if header_index is None:
        header_index = 0
        header_bands = []
        body = records
    else:
        header_bands = [records[header_index]]
        body_start = header_index + 1

        if recognized_layout and body_start < len(records):
            candidate = records[body_start]
            texts = lower_band_labels(candidate)
            if (
                len(texts) >= 3
                and all(re.search(r"[A-Za-z]", text) for text in texts)
                and not is_measure_band(texts)
            ):
                header_bands.append(candidate)
                body_start += 1

            if body_start < len(records):
                candidate = records[body_start]
                texts = lower_band_labels(candidate)
                if len(texts) >= 2 and is_measure_band(texts):
                    header_bands.append(candidate)
                    body_start += 1

        body = records[body_start:]

    width = max(expected_width, max(map(len, records[header_index:])))
    bands = [
        [label(value) for value in row] + [""] * (width - len(row))
        for row in header_bands
    ]
    active = [""] * len(bands)
    columns = []
    used = set()

    for index in range(width):
        explicit = [band[index] for band in bands]
        parts = []
        for level, text in enumerate(explicit):
            if text:
                active[level] = text
                for deeper in range(level + 1, len(active)):
                    active[deeper] = ""
            elif index >= 3 and any(explicit[level + 1:]):
                text = active[level]
            if text and text not in parts:
                parts.append(text)

        base = " / ".join(parts) or f"column_{index + 1}"
        name = base
        suffix = 2
        while name in used:
            name = f"{base} ({suffix})"
            suffix += 1
        used.add(name)
        columns.append(name)

    rows = [row + [""] * (width - len(row)) for row in body]
    return {"columns": columns, "rows": rows}
